356: float mobility(float w){ return smoothstep(0.02, 0.45, w); }
357: 
358: void face(vec2 off, float w, float m, float C, float diffusion, float edge,
359:           inout float dC){
360:   vec2 uv = vUv + off;
361:   float wn = texture(uWet, uv).x;
362:   float g = m * mobility(wn);
363:   if (g <= 0.0) return;
364:   float Cn = texture(uCover, uv).x;
365:   float d = diffusion * g;
366:   // positive: water (and coverage) drifts from this texel toward the drier neighbour
367:   float e = clamp(edge * (w - wn), -0.08, 0.08) * g;
368:   dC += d * (Cn - C) - (e > 0.0 ? e * C : e * Cn);
369: }
370: 
371: void main(){
372:   float w = texture(uWet, vUv).x;
373:   float m = mobility(w);
374:   float C = texture(uCover, vUv).x;
375:   if (m < 0.002){ o0 = vec4(C); return; }
376: 
377:   float p = filmPresence(vUv);
378:   vec2 vel = texture(uVelocity, vUv).xy;
379:   vec2 coord = vUv - uDt * vel * uSimTexel * m;
380:   float gravGate = smoothstep(0.004, 0.08, w);
381:   gravGate *= mix(1.0, smoothstep(uGravityThreshold, uGravityThreshold + 0.05, w), step(0.0001, uGravityThreshold));
382:   gravGate *= pow(clamp(w * 5.0, 0.0, 1.0), uGravityFocus);
383:   coord += vec2(0.0, uGravity * uDt * uGravityGain * gravGate);
384:   float c = mix(C, texture(uCover, coord).x, m * p);
385: 
386:   float brush = 0.0;
387:   if (uBrush.z > 0.0){
388:     vec2 d = vUv - uBrush.xy; d.x *= uAspect;
389:     brush = exp(-dot(d, d) / (uBrush.z * uBrush.z));
390:   }
391:   float diffusion = clamp(uBleed * (0.25 + 1.3 * brush) * 0.3, 0.0, 0.15);
392:   float dC = 0.0;
393:   face(vec2( uTexel.x, 0.0), w, m, C, diffusion, uEdge, dC);
394:   face(vec2(-uTexel.x, 0.0), w, m, C, diffusion, uEdge, dC);
395:   face(vec2(0.0,  uTexel.y), w, m, C, diffusion, uEdge, dC);
396:   face(vec2(0.0, -uTexel.y), w, m, C, diffusion, uEdge, dC);
397: 
398:   // Coverage is a committed alpha in [0, 1]: clamp the transported sum, scaled
399:   // per texel by the film's presence — a paper-white texel keeps its value.
400:   o0 = vec4(clamp(c + dC * p, 0.0, 1.0));
401: }
